# Formal Figure 2: dietary response discovery in GSE292815 (12-week KC pancreas).
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(grid);library(scales)})
set.seed(20261008)
a<-commandArgs(trailingOnly=FALSE);fa<-grep('^--file=',a,value=TRUE);sd<-if(length(fa))dirname(normalizePath(sub('^--file=','',fa[1]))) else getwd();root<-normalizePath(file.path(sd,'..'),mustWork=FALSE)
dd<-file.path(root,'results/12wk_primary/de');ed<-file.path(root,'results/12wk_primary/enrichment');scd<-file.path(root,'results/12wk_primary/scores');rob<-file.path(root,'results/12wk_primary/robustness');figd<-file.path(root,'results/12wk_primary/figures')
rc<-function(f){if(!file.exists(f))stop('Missing input: ',f);read.csv(f,stringsAsFactors=FALSE,check.names=FALSE)}
pal<-c(CD='#BDBDBD',Safflower='#D6604D','HO-Safflower'='#B2182B',Sunflower='#92C5DE','HO-Sunflower'='#2166AC')
th<-theme_bw(base_size=7,base_family='Arial')+theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(linewidth=.2,colour='grey93'),axis.text=element_text(colour='grey25',size=6.2),axis.title=element_text(colour='grey15',size=6),axis.ticks=element_line(linewidth=.3,colour='grey40'),panel.border=element_rect(linewidth=.35,colour='grey30'),strip.background=element_rect(fill='grey95',colour='grey70',linewidth=.2),strip.text=element_text(size=6.2),legend.position='none',plot.tag=element_text(size=9,face='bold'),plot.tag.position=c(.01,.99),plot.margin=margin(3,3,3,3,'mm'))
core<-c('Txnip','Nlrp3','Casp1','Gsdmd','Il1b','Il18')
# (a) Differential-expression volcano for the primary contrast.
de<-rc(file.path(dd,'primary__HO_Safflower_vs_Safflower.csv'));de$neglog10p<--log10(pmax(de$P.Value,.Machine$double.xmin));de$signif<-!is.na(de$adj.P.Val)&de$adj.P.Val<.05&abs(de$logFC)>=1;de$core<-de$gene_symbol%in%core;de$cat<-factor(ifelse(de$core,'PRII core gene',ifelse(de$signif,'FDR < 0.05; |log2FC| >= 1','Other')),levels=c('Other','FDR < 0.05; |log2FC| >= 1','PRII core gene'))
g2a<-ggplot(de,aes(logFC,neglog10p))+geom_point(aes(colour=cat),size=.72,alpha=.58)+geom_vline(xintercept=c(-1,1),linetype='dashed',linewidth=.28,colour='grey60')+geom_hline(yintercept=-log10(.05),linetype='dashed',linewidth=.28,colour='grey60')+geom_text(data=subset(de,core),aes(label=gene_symbol),size=2.2,vjust=-.45,colour='#111111',check_overlap=TRUE)+scale_colour_manual(values=c(Other='grey78','FDR < 0.05; |log2FC| >= 1'='#D6604D','PRII core gene'='#2166AC'))+labs(x='log2 fold-change (HO-Safflower vs Safflower)',y=expression(-log[10]~italic(P)),tag='a')+th+theme(legend.position='bottom',legend.title=element_blank(),legend.text=element_text(size=5.7),legend.key.width=unit(8,'mm'))
# (b) GSEA dot plot. Pyroptosis and inflammasome use frozen fgsea outputs;
# non-core inflammation is recomputed from the same ranked limma t statistics.
ga<-rc(file.path(ed,'primary__HO_Safflower_vs_Safflower__fgsea.csv'));gb<-rc(file.path(ed,'primary__HO_Sunflower_vs_Sunflower__fgsea.csv'));keep<-c('pyroptosis','inflammasome');fr<-rbind(ga[ga$pathway%in%keep,c('pathway','pval','NES','contrast')],gb[gb$pathway%in%keep,c('pathway','pval','NES','contrast')])
noncore<-c('Tnf','Il6','Cxcl1','Cxcl2','Cxcl5','Ccl2','Ccl3','Ccl4','Ccl5','Nfkb1','Rela','Tlr4','Tgfb1','Ptgs2','S100a8','S100a9','Nfkbia','Tnfaip3')
gsea_one<-function(st,set,B=2000){st<-st[is.finite(st)];st<-st[!duplicated(names(st))];st<-sort(st,decreasing=TRUE);set<-intersect(set,names(st));N<-length(st);Nh<-length(set);if(Nh<3)return(c(NES=NA,pval=NA,n=Nh));w<-abs(st);hit<-names(st)%in%set;calc<-function(h){nr<-sum(w[h]);miss<-sum(!h);r<-cumsum(ifelse(h,w/nr,0)-ifelse(!h,1/miss,0));if(abs(min(r))>abs(max(r)))min(r)else max(r)};es<-calc(hit);nul<-replicate(B,calc(sample(hit)));c(NES=es/mean(abs(nul)),pval=(1+sum(abs(nul)>=abs(es)))/(B+1),n=Nh)}
nc<-do.call(rbind,lapply(c('primary__HO_Safflower_vs_Safflower','primary__HO_Sunflower_vs_Sunflower'),function(ct){x<-rc(file.path(dd,paste0(ct,'.csv')));st<-x$t;names(st)<-x$gene_symbol;z<-gsea_one(st,noncore);data.frame(pathway='inflammation_noncore',pval=z['pval'],NES=z['NES'],contrast=ct,n=z['n'])}));fr$n<-NA;enr<-rbind(fr,nc);enr$contrast_label<-ifelse(enr$contrast=='primary__HO_Safflower_vs_Safflower','HO-Safflower vs Safflower','HO-Sunflower vs Sunflower');enr$pathway_label<-c(pyroptosis='Pyroptosis',inflammasome='Inflammasome',inflammation_noncore='Non-core inflammation')[enr$pathway];enr$FDR<-ave(as.numeric(enr$pval),enr$contrast,FUN=function(z)p.adjust(z,'BH'));enr$pathway_label<-factor(enr$pathway_label,levels=c('Non-core inflammation','Inflammasome','Pyroptosis'));enr$contrast_label<-factor(enr$contrast_label,levels=c('HO-Safflower vs Safflower','HO-Sunflower vs Sunflower'))
g2b<-ggplot(enr,aes(NES,pathway_label,colour=contrast_label,size=-log10(pmax(FDR,1e-300))))+geom_vline(xintercept=0,linewidth=.3,colour='grey65')+geom_point(alpha=.92)+facet_wrap(~contrast_label,nrow=1)+scale_colour_manual(values=c('HO-Safflower vs Safflower'='#B2182B','HO-Sunflower vs Sunflower'='#2166AC'))+scale_size_continuous(range=c(1.7,4.2),name=expression(-log[10]~FDR))+labs(x='Normalized enrichment score (NES)',y=NULL,tag='b')+th+theme(legend.position='right',legend.title=element_text(size=5.6),legend.text=element_text(size=5.2),panel.spacing=unit(4,'mm'))
# (c) six-gene heatmap across the 21 samples.
lo<-rc(file.path(scd,'fig2f_six_gene_z_long.csv'));lo$group<-factor(lo$group,levels=c('CD','Safflower','HO-Safflower','Sunflower','HO-Sunflower'));lo$gene<-factor(lo$gene,levels=rev(core));lo$sample<-factor(lo$sample,levels=unique(lo$sample))
g2c<-ggplot(lo,aes(sample,gene,fill=z))+geom_tile(colour='white',linewidth=.25)+facet_grid(~group,scales='free_x',space='free_x')+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',midpoint=0,limits=c(-2.5,2.5),oob=squish,name='Gene-wise\nz-score')+labs(x=NULL,y=NULL,tag='c')+th+theme(legend.position='right',legend.key.size=unit(2.5,'mm'),legend.text=element_text(size=5.2),legend.title=element_text(size=5.5),axis.text.x=element_blank(),axis.ticks.x=element_blank(),axis.text.y=element_text(face='italic',size=6),panel.spacing.x=unit(.8,'mm'))
# (d) six-gene effects for the primary contrast; no score-construction panels are repeated here.
ef<-rc(file.path(figd,'fig2f_six_gene_effects.csv'));ef$gene<-factor(ef$gene,levels=rev(core));g2d<-ggplot(ef,aes(delta_z,gene))+geom_vline(xintercept=0,linetype='dashed',linewidth=.3,colour='grey55')+geom_errorbar(aes(xmin=ci95_lower,xmax=ci95_upper),orientation='y',width=.18,linewidth=.45,colour='#555555')+geom_point(size=1.8,colour='#B2182B')+labs(x='Mean z-score difference',y=NULL,tag='d')+th+theme(axis.text.y=element_text(face='italic',size=6.2),axis.title.x=element_text(size=5.4))
# (e) second oil source, compact directionality summary.
fu<-rc(file.path(scd,'12wk_primary_score_contrasts.csv'));fu<-fu[fu$contrast=='primary__HO_Sunflower_vs_Sunflower'&fu$score%in%c('PSPS_core','pyroptosis_score','inflammasome_score'),];fu$label<-c(PSPS_core='PRII',pyroptosis_score='Pyroptosis score',inflammasome_score='Inflammasome score')[fu$score];no<-rc(file.path(rob,'12wk_noncore_score_contrasts.csv'));no<-no[no$contrast=='primary__HO_Sunflower_vs_Sunflower'&no$score%in%c('pyroptosis_noncore_score','inflammasome_noncore_score','inflammation_noncore_score'),];no$label<-c(pyroptosis_noncore_score='Pyroptosis non-core',inflammasome_noncore_score='Inflammasome non-core',inflammation_noncore_score='Inflammation non-core')[no$score];ee<-rbind(data.frame(label=fu$label,effect=fu$logFC,lo=fu$CI95_lower,hi=fu$CI95_upper,q=fu$padj_BH),data.frame(label=no$label,effect=no$logFC,lo=no$CI95_lower,hi=no$CI95_upper,q=no$padj_BH));ee$label<-factor(ee$label,levels=rev(c('PRII','Pyroptosis score','Inflammasome score','Pyroptosis non-core','Inflammasome non-core','Inflammation non-core')))
g2e<-ggplot(ee,aes(effect,label))+geom_vline(xintercept=0,linetype='dashed',linewidth=.3,colour='grey55')+geom_errorbar(aes(xmin=lo,xmax=hi),orientation='y',width=.18,linewidth=.45,colour='#555555')+geom_point(aes(colour=effect>0),size=1.8)+scale_colour_manual(values=c('TRUE'='#2166AC','FALSE'='#B2182B'))+geom_text(aes(label=paste0('q=',format.pval(q,digits=2,eps=.001))),hjust=-.08,size=1.75,colour='grey25')+scale_x_continuous(expand=expansion(mult=c(.05,.27)))+labs(x='Effect estimate (HO-Sunflower − Sunflower)',y=NULL,tag='e')+th+theme(axis.text.y=element_text(size=5.8),axis.title.x=element_text(size=5.4))
fig2<-g2a/g2b/g2c/(g2d|g2e)+plot_layout(heights=c(1.1,1,1.32,1.02));po<-file.path(sd,'Fig2_PRII_formal.pdf');ti<-file.path(sd,'Fig2_PRII_formal.tiff');ggsave(po,fig2,width=180,height=235,units='mm',device=cairo_pdf);tiff(ti,width=180,height=235,units='mm',res=600,compression='lzw',type='cairo');print(fig2);dev.off();write.csv(enr,file.path(sd,'Fig2_PRII_formal_enrichment_stats.csv'),row.names=FALSE);write.csv(ee,file.path(sd,'Fig2_PRII_formal_directionality_stats.csv'),row.names=FALSE);cat('Wrote\n',po,'\n',ti,'\n',sep='')
